// Tiempo ideal de transferencia = bits / velocidad (sin overhead ni congestión)
const apkMB = 89.1; // peso del APK de Senda (compilación del 23-10-2026)
const bits = (mb) => mb * 8e6; // megabytes decimales -> bits
const fmt = (s) => s < 60 ? s.toFixed(1) + " s" : Math.floor(s / 60) + " min " + Math.round(s % 60) + " s";

console.log("Bajar el APK de 89,1 MB (bajada):");
for (const [nombre, mbps] of [["ADSL lejos de la central", 5], ["ADSL2+ en el techo teórico", 24], ["Cable o fibra económica", 100], ["Fibra de 300", 300], ["Fibra de 1 Gbit/s", 1000]]) {
  console.log(`  ${nombre.padEnd(28)} ${String(mbps).padStart(5)} Mbit/s -> ${fmt(bits(apkMB) / (mbps * 1e6))}`);
}
console.log("\nSubir un video de 2 GB (subida):");
for (const [nombre, mbps] of [["ADSL (subida típica ~1)", 1], ["Cable asimétrico (subida 20)", 20], ["Fibra simétrica de 300", 300]]) {
  console.log(`  ${nombre.padEnd(30)} ${String(mbps).padStart(4)} Mbit/s -> ${fmt(2000 * 8e6 / (mbps * 1e6))}`);
}
